style.css:
@-moz-document domain("codehs.com") {
body {
    background-color: #f9f6f7 !important;  /* very light pastel pink */
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #5a4a6e !important; /* soft muted purple text */
  }
  /* Hide right sidebar (adjust class name if needed) */
  .sidebar-right, .some-sidebar-class {
    display: none !important;
  }
  /* Make main content wider with pastel background */
  .main-content {
    width: 90% !important;
    background-color: #e4d9f2 !important; /* pastel lavender */
    padding: 20px !important;
    border-radius: 12px !important;
    box-shadow: 0 4px 8px rgba(0,0,0,0.05);
  }
  /* Links in pastel teal */
  a {
    color: #76c7c0 !important;
  }
  /* Buttons with pastel peach background */
  button, .btn {
    background-color: #ffd6c0 !important;
    color: #5a4a6e !important;
    border: none !important;
    border-radius: 8px !important;
    padding: 8px 14px !important;
    font-weight: bold !important;
    cursor: pointer !important;
  }
  button:hover, .btn:hover {
    background-color: #ffbca6 !important;
  }
}
